using KuaiYi.Core;
using KuaiYi.Core.Settings;
using KuaiYi.Providers;
using Xunit;
using Protocol=KuaiYi.Providers.ApiProtocol;
namespace KuaiYi.Provider.Tests;
public sealed class FailureVersionSequenceTests
{
    [Theory][InlineData(Protocol.OpenAIChat,false)][InlineData(Protocol.OpenAIChat,true)][InlineData(Protocol.AnthropicMessages,false)][InlineData(Protocol.AnthropicMessages,true)]
    public async Task ConsecutiveFailedRecoveryNeverReusesTheRetainedSessionsVersionNumber(Protocol protocol,bool stream)
    {
        await using var r=await TextUsageRig.Create(protocol,stream);var a=r.Start(r.Source("PUBLIC SOURCE A"));await r.Requests(1);await r.Reply(r.Counts(10,1),"PUBLIC COMPLETE A1");var original=r.Version(a);
        var b=r.Start(r.Source("PUBLIC SOURCE B",SelectionSourceKind.OleDrop));await r.Requests(2);await r.Reply(r.Counts(20,2),"PUBLIC PARTIAL B1",finish:protocol==Protocol.OpenAIChat?"length":"max_tokens");Assert.Equal(a.VersionId,r.Results.SelectedVersionId);Assert.Equal(original,r.Version(a));Assert.Equal(1,r.Version(b).Number);r.Window.SelectFailureVersionForTest(b.VersionId);Assert.Equal("PUBLIC SOURCE B",r.Flow.SelectedSnapshot!.Source.Text);Assert.Equal(2,r.Flow.NextGeneration!.VersionNumber);
        for(int expected=2;expected<=5;expected++)
        {
            int requests=r.Script.Requests;var offer=Assert.IsType<KuaiYi.Providers.TextTranslationOffer>(r.Flow.PrepareRegeneration());Assert.Equal(requests,r.Script.Requests);Assert.Equal(expected,offer.Snapshot.VersionNumber);Assert.Equal(b.SessionId,offer.Session);Assert.Equal("PUBLIC SOURCE B",offer.Snapshot.Source.Text);Assert.Equal(TextSubmission.Started,r.Flow.Submit(offer));var next=r.Results.Identity!.Value;Assert.NotEqual(b,next);Assert.Equal(b.SessionId,next.SessionId);Assert.Equal(expected,r.Version(next).Number);Assert.Null(r.Version(next).Failure);Assert.Equal(TranslationUsage.Unknown,r.Version(next).Usage);await r.Requests(expected+1);await r.Reply(r.Counts(expected*10,expected),"PUBLIC PARTIAL B"+expected,finish:protocol==Protocol.OpenAIChat?"length":"max_tokens");
            var failed=r.Version(next);Assert.Equal(expected,failed.Number);Assert.Equal(TranslationFailureReason.OutputTruncated,failed.Failure);Assert.Equal(new TranslationUsage(expected*10,expected),failed.Usage);Assert.Equal(b.VersionId,r.Results.SelectedVersionId);Assert.Equal("PUBLIC PARTIAL B1",r.Results.Text);Assert.Equal(new TranslationUsage(20,2),r.Version(b).Usage);Assert.Equal(expected+1,r.Flow.NextGeneration!.VersionNumber);Assert.Equal(expected+1,r.Results.NextVersionNumber(b.SessionId));Assert.InRange(r.Results.Versions.Count,1,3);Assert.Equal(r.Results.Versions.Count,r.Flow.RetainedSnapshotCount);Assert.All(r.Results.Versions.GroupBy(v=>(v.Identity.SessionId,v.Number)),g=>Assert.Single(g));Assert.False(r.Results.Append(next,"PUBLIC LATE"));Assert.False(r.Results.ObserveUsage(next,999,999));Assert.False(r.Results.Fail(next,"AUTH_FAILED"));Assert.Equal(failed,r.Version(next));
        }
        Assert.Equal(6,r.Script.Requests);Assert.False(r.Gate.HasRunningGeneration);Assert.True(await r.Window.ClearContentForTest());Assert.Empty(r.Results.Versions);Assert.Null(r.Results.LastFailure);Assert.Equal(0,r.Flow.RetainedSnapshotCount);Assert.Equal("",r.Window.FailureNoticeText);
    }
    [Theory][InlineData(Protocol.OpenAIChat,false)][InlineData(Protocol.OpenAIChat,true)][InlineData(Protocol.AnthropicMessages,false)][InlineData(Protocol.AnthropicMessages,true)]
    public async Task AutomaticRollbackAnnouncesNewestAttemptAndExplicitOldSelectionShowsItsOwnFailure(Protocol protocol,bool stream)
    {
        await using var r=await TextUsageRig.Create(protocol,stream);var a=r.Start();await r.Requests(1);await r.Reply(null,"PUBLIC COMPLETE A1");var b=r.Start(r.Source("PUBLIC SOURCE B",SelectionSourceKind.OleDrop));await r.Requests(2);await r.Reply(r.Counts(20,2),"PUBLIC PARTIAL B1",finish:protocol==Protocol.OpenAIChat?"length":"max_tokens");r.Window.SelectFailureVersionForTest(b.VersionId);var b2=r.Start(regenerate:true);await r.Requests(3);await r.Reply(r.Counts(30,3),"PUBLIC PARTIAL B2",finish:protocol==Protocol.OpenAIChat?"content_filter":"refusal");
        Assert.Equal(b.VersionId,r.Results.SelectedVersionId);Assert.Equal("PUBLIC PARTIAL B1",r.Results.Text);Assert.Equal(TranslationFailureReason.OutputTruncated,r.Version(b).Failure);Assert.Equal(TranslationFailureReason.ContentRefused,r.Version(b2).Failure);Assert.Equal(b2,r.Results.LastFailure!.Identity);Assert.Contains("新尝试未完成",r.Window.FailureNoticeText);Assert.Contains("正文为旧结果",r.Window.FailureNoticeText);Assert.StartsWith("版本 2 · 拖放文字",r.Window.FailureNoticeFull);Assert.Contains("模型未提供",r.Window.FailureNoticeFull);Assert.Contains("此原因属于上述失败尝试",r.Window.FailureAutomation);
        r.Window.SelectFailureVersionForTest(b.VersionId);Assert.StartsWith("版本 1 · 拖放文字",r.Window.FailureNoticeFull);Assert.Contains("达到模型输出限制",r.Window.FailureNoticeFull);Assert.DoesNotContain("新尝试未完成",r.Window.FailureNoticeText);Assert.Equal("PUBLIC PARTIAL B1",r.Results.Text);Assert.Equal(new TranslationUsage(20,2),r.Version(b).Usage);r.Window.SelectFailureVersionForTest(b2.VersionId);Assert.Equal("PUBLIC PARTIAL B2",r.Results.Text);Assert.Contains("模型未提供",r.Window.FailureNoticeFull);Assert.Equal(new TranslationUsage(30,3),r.Version(b2).Usage);Assert.Equal(3,r.Flow.NextGeneration!.VersionNumber);Assert.Equal(3,r.Script.Requests);
        r.Window.SelectFailureVersionForTest(b.VersionId);var b3=r.Start(regenerate:true);Assert.Equal(3,r.Version(b3).Number);await r.Requests(4);await r.Reply(r.Counts(40,4),"PUBLIC PARTIAL B3",finish:protocol==Protocol.OpenAIChat?"content_filter":"refusal");Assert.Equal(b.VersionId,r.Results.SelectedVersionId);Assert.Equal("PUBLIC PARTIAL B1",r.Results.Text);Assert.Equal(b3,r.Results.LastFailure!.Identity);Assert.Contains("新尝试未完成",r.Window.FailureNoticeText);Assert.StartsWith("版本 3 · 拖放文字",r.Window.FailureNoticeFull);Assert.Contains("模型未提供",r.Window.FailureNoticeFull);r.Window.SelectFailureVersionForTest(b.VersionId);Assert.StartsWith("版本 1 · 拖放文字",r.Window.FailureNoticeFull);Assert.Contains("达到模型输出限制",r.Window.FailureNoticeFull);Assert.Equal(new TranslationUsage(20,2),r.Version(b).Usage);Assert.Equal(new TranslationUsage(40,4),r.Version(b3).Usage);Assert.Equal(4,r.Flow.NextGeneration!.VersionNumber);Assert.Equal(4,r.Script.Requests);Assert.True(await r.Window.ClearContentForTest());Assert.Equal("",r.Window.FailureNoticeText);
    }
    [Theory][InlineData(false)][InlineData(true)]
    public void FailAndNeutralAbandonRetainTheNewestOrdinalWhenFallbackIsTheSameSession(bool abandon)
    {
        var gate=new RuntimeGate();var origin=new EndpointOrigin(new Uri("https://public.invalid"));gate.ConsentTo(origin);Assert.True(gate.TryEnable(origin,true));var results=new OverlayResults(gate);
        RequestIdentity Start(Guid session){Assert.True(gate.TryStartRequest(session,Guid.NewGuid(),null,out var id,out _));Assert.True(results.Begin(id));return id;}
        var a=Start(Guid.NewGuid());results.Append(a,"PUBLIC A1");results.Complete(a);var sessionB=Guid.NewGuid();var b=Start(sessionB);results.Append(b,"PUBLIC B1");Assert.True(results.Fail(b,"OUTPUT_TRUNCATED"));Assert.Equal(a.VersionId,results.SelectedVersionId);Assert.True(results.SelectVersion(b.VersionId));var b2=Start(sessionB);Assert.Equal(2,results.Versions.Single(v=>v.Identity==b2).Number);Assert.True(abandon?results.Abandon(b2):results.Fail(b2,"CONTENT_REFUSED"));Assert.Equal(b.VersionId,results.SelectedVersionId);Assert.Equal(3,results.NextVersionNumber(sessionB));var b3=Start(sessionB);Assert.Equal(3,results.Versions.Single(v=>v.Identity==b3).Number);Assert.False(results.Fail(b2,"AUTH_FAILED"));Assert.False(results.Append(b3 with{RequestId=Guid.NewGuid()},"PUBLIC FORGED"));gate.StopRequest(b3);Assert.False(results.Fail(b3,"AUTH_FAILED"));Assert.False(results.Abandon(b3));Assert.InRange(results.RetainedVersionIds.Count,1,3);results.Clear();Assert.Empty(results.Versions);Assert.Equal(1,results.NextVersionNumber(sessionB));
    }

}
